<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import { training, writeTraining } from '../api/training'
import type { ReviewItem } from '../models/training'
const props = defineProps<{ item: ReviewItem }>(), emit = defineEmits<{ saved: [] }>(), route = useRoute()
const mode = ref(route.query.attemptId ? 'ATTEMPT' : 'TRAINING'), sourceId = ref(String(route.query.attemptId || route.query.trainingLinkId || '')), error = ref(''), busy = ref(false)
const options = ref<{ id: string; text: string; checkId?: string; index?: number; kind?: string; reportText?: string }[]>([]), chosen = reactive<Record<string, string>>({}), reasons = reactive<Record<string, string>>({}), coverage = reactive<Record<string, boolean>>({}), findings = ref<string[]>([])
async function read() { busy.value = true; error.value = ''; try { options.value = []; if (mode.value === 'ATTEMPT') { const a = await training<any>(`/practice-attempts/${sourceId.value}`); if (a.status !== 'READY') throw new Error('该作答的反馈尚未就绪，请先完成或恢复评估。'); options.value = (a.evaluation?.result?.checks || []).map((c: any) => ({ id: c.checkId, checkId: c.checkId, text: `${{ MET: '满足', GAP: '有缺口', UNCERTAIN: '无法判断' }[c.status as string]}：${c.explanation}` })) } else { const link = await training<any>(`/training-links/${sourceId.value}`); if (!link.sessionId) throw new Error('该来源尚未开始练习。'); const report = await training<any>(`/api/sessions/${link.sessionId}/report`); for (const q of report.questions) for (const kind of ['correct', 'incorrect', 'missing', 'uncertain']) for (const text of q[kind] || []) options.value.push({ id: String(options.value.length), text: `第 ${q.questionIndex + 1} 题：${text}`, index: q.questionIndex, kind, reportText: text }) } } catch (e) { error.value = e instanceof Error ? e.message : '读取证据失败' } finally { busy.value = false } }
async function save(resolve = false) { busy.value = true; error.value = ''; try { const selected = findings.value.map(fid => { const o = options.value.find(x => x.id === chosen[fid]); if (!o) throw new Error('请为每个所选发现绑定一条具体结论。'); return { findingId: fid, coverageConfirmed: !!coverage[fid], reason: reasons[fid] || '', ...(mode.value === 'ATTEMPT' ? { checkId: o.checkId } : { reportKind: o.kind, reportText: o.reportText }), option: o } }); if (mode.value === 'TRAINING' && new Set(selected.map(b => b.option.index)).size > 1) throw new Error('一次仅确认同一报告题目的覆盖关系；其他题目请分别确认。'); await writeTraining(`/review-items/${props.item.id}/actions`, { expectedVersion: props.item.revision, action: resolve ? 'RESOLVE_EVIDENCE' : 'CONFIRM_EVIDENCE', findingIds: findings.value, bindings: selected.map(({ option: _, ...b }) => b), ...(mode.value === 'ATTEMPT' ? { attemptId: sourceId.value } : { trainingLinkId: sourceId.value, evidenceQuestionIndex: selected[0]?.option.index }) }); emit('saved') } catch (e) { error.value = e instanceof Error ? e.message : '保存失败，选择保留。' } finally { busy.value = false } }
onMounted(() => { if (sourceId.value) void read() })
</script>
<template><section class="training-flow training-preview"><h3>带着结果回来，逐条核对覆盖关系</h3><p class="tiny muted">报告任意一道题“正确”不能自动支持全部发现。请明确选中本次覆盖的发现，并绑定同题结论或检查点。</p><p v-if="error" class="notice" role="alert">{{ error }}</p><label for="evidence-mode">证据来源</label><select id="evidence-mode" v-model="mode" @change="options = []"><option value="TRAINING">已完成专项报告</option><option value="ATTEMPT">同题独立作答的初始评估</option></select><label for="evidence-source">来源 ID（从报告或作答返回时自动带入）</label><input id="evidence-source" v-model="sourceId" /><button class="btn btn-secondary" :disabled="busy || !sourceId" @click="read">读取证据</button><div v-for="f in item.findings.filter(f => f.confirmed && !f.disputed)" :key="f.id" class="training-quote"><label class="training-inline-check"><input v-model="findings" type="checkbox" :value="f.id" />{{ f.text }}</label><template v-if="findings.includes(f.id)"><label :for="`binding-${f.id}`">实际对应的结论或检查点</label><select :id="`binding-${f.id}`" v-model="chosen[f.id]"><option value="">请选择逐条依据</option><option v-for="o in options" :key="o.id" :value="o.id">{{ o.text }}</option></select><label :for="`reason-${f.id}`">说明它为何覆盖这条发现</label><textarea :id="`reason-${f.id}`" v-model="reasons[f.id]" maxlength="1000" rows="2" /><label class="training-inline-check"><input v-model="coverage[f.id]" type="checkbox" />我已核对对应原文与覆盖范围</label></template></div><button class="btn btn-primary" :disabled="busy || !findings.length" @click="save()">保存所选发现的补充观察</button><button v-if="item.status === 'WAITING_EVIDENCE'" class="btn btn-secondary" :disabled="busy || !findings.length" @click="save(true)">证据支持且无剩余未知时，结束待证事项</button><p class="tiny muted">模型仍无法判断时保持未知；用户确认不等于客观证明或能力提升。</p></section></template>
